import { useState } from "react"
import TodoList from "./TodoList";


export default function TodoForm(){
     return
    <div>
        <form action='#' method="GET" onSubmit={(e)=>{
            e.preventDefault();
            setTodoList(list=>[...list,todoText]);
            setTodoText('')
        }}>
            <textarea
             value={todoText}
             onChange={(e)=>{
                setTodoText(e.target.value)
             }}
            ></textarea>
            <button>Save</button>
        </form>
        </div>
}
